// Showcase imagery: real outputs from the PixelDuo case gallery (public/showcase).
//
// Variants are pre-generated by scripts/gen-image-variants.ts: each is cropped to
// the aspect its slot already renders (the CSS uses object-fit: cover over a fixed
// aspect-ratio, so the cropped-away pixels were never visible) and encoded at the
// densities the layout asks for. The originals were 600x900 to 3072x1024 JPEGs —
// the marquee showed a 3:1 photo through a 4:5 window at 280px wide, shipping ~11x
// the pixels anyone could see. The hero's 2x rung stops at 960 because the sources
// are only 941px (case1) and 600px (case225) wide: a 1440 rung would be interpolation
// worth 224KB.
const SLOT_W = { hero: [720, 960], mq: [320, 640], how: [420, 840] } as const;
type Slot = keyof typeof SLOT_W;
const IMG = (n: number, slot: Slot) => `/showcase/case${n}-${slot}-${SLOT_W[slot][0]}.webp`;
const IMG_SET = (n: number, slot: Slot) =>
  SLOT_W[slot].map((w) => `/showcase/case${n}-${slot}-${w}.webp ${w}w`).join(", ");
// Rendering widths measured at a 1440 viewport (the .hero single-column breakpoint is
// 960px): compare box 641px, marquee item 280px, how-cell image 391px.
const HERO_SIZES = "(min-width: 961px) 641px, calc(100vw - 40px)";
const MQ_SIZES = "(min-width: 1400px) 280px, 20vw";
const HOW_SIZES = "(min-width: 961px) 400px, calc(100vw - 40px)";

